import Foundation
enum SM64BetaTrampolineRole: UInt8, Equatable, Sendable { case top = 0; case spring = 1 }
struct SM64BetaTrampolineOutput: Equatable, Sendable { let role: SM64BetaTrampolineRole; let position: SM64ObjectVector3; let faceAngles: SM64ObjectAngles; let scaleY: Float; let marioOnTrampoline: Bool; let spawnSpring: Bool }
enum SM64BetaTrampolineBehavior { static func update(role:SM64BetaTrampolineRole,timer:Int32,position:SM64ObjectVector3,homePosition:SM64ObjectVector3,faceAngles:SM64ObjectAngles,parentPosition:SM64ObjectVector3,parentFaceAngles:SM64ObjectAngles,marioOn:Bool)->SM64BetaTrampolineOutput{if role == .top{let on=marioOn;return .init(role:role,position:on ? position:homePosition,faceAngles:faceAngles,scaleY:1,marioOnTrampoline:on,spawnSpring:timer == 0)};var p=parentPosition;p.y -= 75;let d=p.y-homePosition.y;let scale=d >= 0 ? d/10+1 : 1-(-d)/500;return .init(role:role,position:p,faceAngles:parentFaceAngles,scaleY:scale,marioOnTrampoline:false,spawnSpring:false)} }
